SELECT i.id, i.last_restock, i.product_id, i.quantity, ss.revenue, ss.units, CAST(ss.revenue AS INT) AS revenue_int FROM inventory i INNER JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id WHERE i.product_id IN (2, 5, 10) AND i.quantity <= 61 ORDER BY revenue_int DESC
